}
fields[16] = "invalid"
if err := verifyNativeExecNice(stat()); err == nil {
	t.Fatal("malformed nice was accepted")
}
fields[0] = "Z"
if err := verifyNativeExecNice(stat()); err == nil {
	t.Fatal("zombie status was accepted")
}
