func nativeDelegatedServiceRoot(membership string) (string, error) {
	if !filepath.IsAbs(membership) || filepath.Clean(membership) != membership {
		return "", errNativeSubgroupRequired
	}
	service, ok := strings.CutSuffix(membership, "/supervisor")
	if !ok || service == "" || service == "/" || !strings.HasSuffix(filepath.Base(service), ".service") {
		return "", errNativeSubgroupRequired
	}
	return filepath.Join("/sys/fs/cgroup", service), nil
}

func setNativeSupervisorOOMPreference(path string) error {
	if err := unix.Setxattr(path, "user.oomd_omit", []byte("1"), 0); err != nil {
		return err
	}
	if err := removeNativeOOMXattr(path, "user.oomd_avoid"); err != nil {
		return err
	}
	value, present, err := readNativeOOMXattr(path, "user.oomd_omit")
	if err != nil {
		return err
	}
	if !present || value != "1" {
		return errors.New("native supervisor omit xattr readback differs")
	}
	return nil
}

func clearNativeWorkloadOOMPreference(path string) error {
	for _, name := range []string{"user.oomd_omit", "user.oomd_avoid"} {
		if err := removeNativeOOMXattr(path, name); err != nil {
			return err
		}
		_, present, err := readNativeOOMXattr(path, name)
		if err != nil {
			return err
		}
		if present {
			return fmt.Errorf("native workload retained %s xattr", name)
		}
	}
	return nil
}

func removeNativeOOMXattr(path, name string) error {
	err := unix.Removexattr(path, name)
	if err != nil && !errors.Is(err, unix.ENODATA) {
		return err
	}
	return nil
}

func readNativeOOMXattr(path, name string) (string, bool, error) {
	var value [16]byte
	count, err := unix.Getxattr(path, name, value[:])
	if errors.Is(err, unix.ENODATA) {
		return "", false, nil
	}
	if err != nil {
		return "", false, err
	}
	return string(value[:count]), true, nil
}

func configureNativeRoleResources(path string, quota uint64) error {
	for _, name := range []string{"memory.min", "memory.low"} {
		if err := setNativeResourceValue(filepath.Join(path, name), 0); err != nil {
			return fmt.Errorf("remove native workload %s protection: %w", name, err)
		}
	}
	if err := setNativeResourceValue(filepath.Join(path, "cpu.weight"), nativeWorkloadCPUWeight); err != nil {
		return fmt.Errorf("weight native workload CPU: %w", err)
	}
	if err := setNativeIOWeight(filepath.Join(path, "io.weight"), nativeWorkloadCPUWeight); err != nil {
		return fmt.Errorf("weight native workload I/O: %w", err)
	}
	if err := clearNativeWorkloadOOMPreference(path); err != nil {
		return fmt.Errorf("keep native workload eligible for systemd-oomd: %w", err)
	}
	return setNativeCPUMax(filepath.Join(path, "cpu.max"), quota)
}

func clearNativeWorkloadOOMPreference(path string) error {
	for _, name := range []string{"user.oomd_omit", "user.oomd_avoid"} {
		if err := removeNativeOOMXattr(path, name); err != nil {
			return err
		}
		_, present, err := readNativeOOMXattr(path, name)
		if err != nil {
			return err
		}
		if present {
			return fmt.Errorf("native workload retained %s xattr", name)
		}
	}
	return nil
}

func removeNativeOOMXattr(path, name string) error {
	err := unix.Removexattr(path, name)
	if err != nil && !errors.Is(err, unix.ENODATA) {
		return err
	}
	return nil
}

func readNativeOOMXattr(path, name string) (string, bool, error) {
	var value [16]byte
	count, err := unix.Getxattr(path, name, value[:])
	if errors.Is(err, unix.ENODATA) {
		return "", false, nil
	}
	if err != nil {
		return "", false, err
	}
	return string(value[:count]), true, nil
}

func setNativeCPUMax(path string, quota uint64) error {
	if quota < 1000 {
		return errors.New("native CPU cap is below the kernel minimum")
	}
	want := strconv.FormatUint(quota, 10) + " " + strconv.FormatUint(nativeCPUPeriod, 10)
	if err := os.WriteFile(path, []byte(want), 0600); err != nil {
		return err
	}
	readback, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if strings.Join(strings.Fields(string(readback)), " ") != want {
		return errors.New("native CPU cap readback differs from requested value")
	}
	return nil
}

func setNativeIOWeight(path string, value uint64) error {
	want := strconv.FormatUint(value, 10)
	if err := os.WriteFile(path, []byte("default "+want), 0600); err != nil {
		return err
	}
	readback, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	for line := range strings.SplitSeq(strings.TrimSpace(string(readback)), "\n") {
		fields := strings.Fields(line)
		if len(fields) == 2 && fields[0] == "default" && fields[1] == want {
			return nil
		}
	}
	return errors.New("native cgroup I/O weight readback differs from requested value")
}

func readNativeResourceValue(path string) (uint64, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return 0, err
	}
	value, err := strconv.ParseUint(strings.TrimSpace(string(data)), 10, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid native cgroup resource value: %w", err)
	}
	return value, nil
}

func setNativeResourceValue(path string, value uint64) error {
	if err := os.WriteFile(path, []byte(strconv.FormatUint(value, 10)), 0600); err != nil {
		return err
	}
	readback, err := readNativeResourceValue(path)
	if err != nil {
		return err
	}
	if readback != value {
		return fmt.Errorf("native cgroup resource readback %d differs from requested %d", readback, value)
	}
	return nil
}

func validateNativeSupervisorReservationAt(mountRoot, serviceRoot, runnerRoot string, signedReserve uint64) error {
	if !filepath.IsAbs(serviceRoot) || filepath.Dir(runnerRoot) != serviceRoot ||
		!strings.HasPrefix(serviceRoot, mountRoot+string(filepath.Separator)) {
		return errors.New("native supervisor reservation has invalid cgroup roots")
	}
	if signedReserve == 0 || signedReserve%uint64(os.Getpagesize()) != 0 {
		return errors.New("managed system reserve must be positive and page-aligned")
	}
	supervisor := filepath.Join(serviceRoot, "supervisor")
	minimum, err := readNativeResourceValue(filepath.Join(serviceRoot, "memory.min"))
	if err != nil {
		return fmt.Errorf("read native service memory.min: %w", err)
	}
	low, err := readNativeResourceValue(filepath.Join(serviceRoot, "memory.low"))
	if err != nil {
		return fmt.Errorf("read native service memory.low: %w", err)
	}
	if minimum == 0 || minimum%uint64(os.Getpagesize()) != 0 || low%uint64(os.Getpagesize()) != 0 ||
		minimum > low || low > signedReserve {
		return errors.New("native service memory protection is absent or exceeds the signed reserve")
	}
	for ancestor := filepath.Dir(serviceRoot); ancestor != mountRoot; ancestor = filepath.Dir(ancestor) {
		for _, protection := range []struct {
			name string
			want uint64
		}{{"memory.min", minimum}, {"memory.low", low}} {
			value, err := readNativeResourceValue(filepath.Join(ancestor, protection.name))
			if err != nil {
				return fmt.Errorf("read native ancestor %s: %w", protection.name, err)
			}
			if value < protection.want {
				return fmt.Errorf("native ancestor %s does not preserve supervisor reservation", protection.name)
			}
		}
	}
	for _, name := range []string{"memory.min", "memory.low"} {
		serviceValue, err := readNativeResourceValue(filepath.Join(serviceRoot, name))
		if err != nil {
			return err
		}
		supervisorValue, err := readNativeResourceValue(filepath.Join(supervisor, name))
		if err != nil {
			return err
		}
		if supervisorValue != serviceValue {
			return fmt.Errorf("native supervisor %s differs from service protection", name)
		}
		runnerValue, err := readNativeResourceValue(filepath.Join(runnerRoot, name))
		if err != nil {
			return err
		}
		if runnerValue != 0 {
			return fmt.Errorf("native runner retained %s protection", name)
		}
	}
	return nil
}

func readNativeResourceValue(path string) (uint64, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return 0, err
	}
	value, err := strconv.ParseUint(strings.TrimSpace(string(data)), 10, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid native cgroup resource value: %w", err)
	}
	return value, nil
}

func deriveNativeWorkloadCPUQuotaAt(mountRoot, serviceRoot string, availableCPUs int) (uint64, error) {
	if availableCPUs <= 0 || availableCPUs > 1024 || !strings.HasPrefix(serviceRoot, mountRoot+string(filepath.Separator)) {
		return 0, errors.New("native CPU quota has invalid cgroup root or affinity")
	}
	available := uint64(availableCPUs) * nativeCPUPeriod
	for ancestor := serviceRoot; ancestor != mountRoot; ancestor = filepath.Dir(ancestor) {
		data, err := os.ReadFile(filepath.Join(ancestor, "cpu.max"))
		if err != nil {
			return 0, fmt.Errorf("read native ancestor CPU cap: %w", err)
		}
		fields := strings.Fields(string(data))
		if len(fields) != 2 {
			return 0, errors.New("native ancestor CPU cap is malformed")
		}
		period, err := strconv.ParseUint(fields[1], 10, 64)
		if err != nil || period < 1000 || period > 1000000 {
			return 0, errors.New("native ancestor CPU period is malformed")
		}
		if fields[0] != "max" {
			quota, err := strconv.ParseUint(fields[0], 10, 64)
			if err != nil || quota == 0 {
				return 0, errors.New("native ancestor CPU quota is malformed")
			}
			// Quotas greater than CPU affinity cannot narrow the effective cap.
			// This comparison also bounds multiplication in the next branch.
			if quota < uint64(availableCPUs)*period {
				available = min(available, quota*nativeCPUPeriod/period)
			}
		}
	}
	// Bound the aggregate runner and each role to 75% of the effective
	// ancestor/affinity budget. The remaining quarter is left for the manager.
	quota := available * 3 / 4
	if quota < 1000 || quota >= available {
		return 0, errors.New("native CPU budget leaves no safe supervisor headroom")
	}
	return quota, nil
}

func requireEmptyCgroup(path string) error {
	procs, err := os.ReadFile(filepath.Join(path, "cgroup.procs"))
	if err != nil {
		return err
	}
	if strings.TrimSpace(string(procs)) != "" {
		return errors.New("cgroup contains processes")
	}
	return nil
}

func prepareNativeCgroupRoot(root string) error {
	parent := filepath.Dir(root)
	if err := requireEmptyCgroup(parent); err != nil {
		return fmt.Errorf("native service cgroup must stay process-free: %w", err)
	}
	if err := enableCgroupMemoryController(parent); err != nil {
		return fmt.Errorf("enable native service memory controller: %w", err)
	}
	if err := enableCgroupCPUController(parent); err != nil {
		return fmt.Errorf("enable native service CPU controller: %w", err)
	}
	if err := enableCgroupIOController(parent); err != nil {
		return fmt.Errorf("enable native service I/O controller: %w", err)
	}
	if err := os.MkdirAll(root, 0700); err != nil {
		return fmt.Errorf("create native runner cgroup: %w", err)
	}
	if err := requireEmptyCgroup(root); err != nil {
		return fmt.Errorf("native runner cgroup must be process-free: %w", err)
	}
	if err := enableCgroupMemoryController(root); err != nil {
		return fmt.Errorf("enable native runner memory controller: %w", err)
	}
	if err := enableCgroupCPUController(root); err != nil {
		return fmt.Errorf("enable native runner CPU controller: %w", err)
	}
	if err := enableCgroupIOController(root); err != nil {
		return fmt.Errorf("enable native runner I/O controller: %w", err)
	}
	if err := configureNativeSiblingResources(parent, root); err != nil {
		return err
	}
	quota, err := deriveNativeWorkloadCPUQuota(parent)
	if err != nil {
		return err
	}
	return setNativeCPUMax(filepath.Join(root, "cpu.max"), quota)
}

func enableCgroupMemoryController(parent string) error {
	return enableCgroupController(parent, "memory")
}

func enableCgroupCPUController(parent string) error {
	return enableCgroupController(parent, "cpu")
}

func enableCgroupIOController(parent string) error {
	return enableCgroupController(parent, "io")
}

func enableCgroupController(parent, controller string) error {
	path := filepath.Join(parent, "cgroup.subtree_control")
	file, err := os.OpenFile(path, os.O_WRONLY, 0)
	if err != nil {
		return err
	}
	if _, err := file.WriteString("+" + controller); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	readback, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if !slices.Contains(strings.Fields(string(readback)), controller) {
		return fmt.Errorf("kernel cgroup.subtree_control does not include %s: %q", controller, strings.TrimSpace(string(readback)))
	}
	return nil
}

func tenantCgroupMode(info os.FileInfo, identity WorkloadIdentity) (uint32, error) {
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok {
		return 0, errors.New("cannot inspect native cgroup ownership")
	}
	permissions := uint32(info.Mode().Perm())
	switch {
	case owner.Uid == identity.UID:
		return permissions >> 6 & 7, nil
	case owner.Gid == identity.GID:
		return permissions >> 3 & 7, nil
	default:
		return permissions & 7, nil
	}
}

// The workload has no supplementary groups or capabilities, so these mode
// checks match the credentials it will use after the native helper drops root.
func validateTenantCgroupTraversal(path string, identity WorkloadIdentity) error {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return errors.New("native cgroup path must be absolute and clean")
	}
	for directory := path; ; directory = filepath.Dir(directory) {
		info, err := os.Lstat(directory)
		if err != nil {
			return fmt.Errorf("inspect native cgroup ancestor %s: %w", directory, err)
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("native cgroup ancestor %s is not a directory", directory)
		}
		mode, err := tenantCgroupMode(info, identity)
		if err != nil {
			return fmt.Errorf("inspect native cgroup ancestor %s: %w", directory, err)
		}
		if mode&1 == 0 || mode&2 != 0 {
			return fmt.Errorf("workload cannot safely traverse native cgroup ancestor %s", directory)
		}
		if directory == "/" {
			return nil
		}
	}
}

func verifyNativeExecNice(stat []byte) error {
	closing := bytes.LastIndexByte(stat, ')')
	if closing < 0 {
		return errors.New("native target has invalid process status")
	}
	fields := strings.Fields(string(stat[closing+1:]))
	if len(fields) <= 16 || fields[0] == "Z" || fields[0] == "X" || fields[0] == "x" {
		return errors.New("native target exited before verification")
	}
	// fields[0] is stat field 3 (state); fields[16] is field 19 (nice).
	// fields[17] is num_threads and cannot detect an inherited negative nice.
	nice, err := strconv.Atoi(fields[16])
	if err != nil || nice < 0 {
		return errors.New("native target retained protected supervisor nice")
	}
	return nil
}

func resetNativeWorkloadOOMScore(path string) error {
	oomScore, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("read native workload OOM score adjustment: %w", err)
	}
	currentOOM := strings.TrimSpace(string(oomScore))
	adjustment, err := strconv.Atoi(currentOOM)
	if err != nil || adjustment < -1000 || adjustment > 1000 {
		return fmt.Errorf("invalid inherited native workload OOM score adjustment %q", currentOOM)
	}
	if adjustment >= 0 {
		return nil
	}
	if err := os.WriteFile(path, []byte("0"), 0); err != nil {
		return fmt.Errorf("reset native workload OOM score adjustment from %d: %w", adjustment, err)
	}
	oomScore, err = os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("verify native workload OOM score adjustment: %w", err)
	}
	if strings.TrimSpace(string(oomScore)) != "0" {
		return fmt.Errorf("native workload OOM score adjustment did not reset: %q", strings.TrimSpace(string(oomScore)))
	}
	return nil
}

func validNativeExecRequest(request nativeExecRequest) bool {
	return request.Path != "" && len(request.Args) != 0 && request.ParentPID >= 2 &&
		request.Identity.UID != 0 && request.Identity.GID != 0 && request.ExtraFileCount != nil &&
		validateNativeTargetExtraFileCount(*request.ExtraFileCount) == nil
}

func validateNativeTargetExtraFileCount(count int) error {
	if count < 0 || count > maxNativeTargetExtraFiles {
		return errors.New("native target supports at most one inherited file")
	}
	return nil
}

func launchNativeWorkload(ctx context.Context, target *exec.Cmd, cgroup *os.File, cgroupPath string, identity WorkloadIdentity) (*exec.Cmd, func(), <-chan error, error) {
	if !filepath.IsAbs(cgroupPath) || filepath.Clean(cgroupPath) != cgroupPath {
		return nil, nil, nil, errors.New("native launch requires an absolute cgroup path")
	}
	if err := validateNativeTargetExtraFileCount(len(target.ExtraFiles)); err != nil {
		return nil, nil, nil, err
	}
	if err := requireNativeSupervisorKillCapability(); err != nil {
		return nil, nil, nil, err
	}

func testNativeTargetExtraFileChild(t *testing.T, scenario string) {
	t.Helper()
	pollRead, pollWrite, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	defer pollRead.Close()
	defer pollWrite.Close()
	if err := pollRead.SetReadDeadline(time.Now().Add(time.Second)); err != nil {
		t.Fatal(err)
	}
	count := 0
	if scenario != "zero" {
		count = 1
	}
	if scenario == "missing" {
		if err := unix.Close(5); err != nil {
			t.Fatal(err)
		}
		if err := remapNativeTargetExtraFiles(count); !errors.Is(err, unix.EBADF) {
			t.Fatalf("missing inherited target FD = %v, want EBADF", err)
		}
	} else {
		if err := remapNativeTargetExtraFiles(count); err != nil {
			t.Fatal(err)
		}
		fd := 5
		if count == 1 {
			fd = 3
		}
		assertNativeTestFDContent(t, fd, "target-file")
	}
	assertNativeTestFDContent(t, 6, "unrelated-file")
	if _, err := pollWrite.Write([]byte{'x'}); err != nil {
		t.Fatal(err)
	}
	var one [1]byte
	if _, err := pollRead.Read(one[:]); err != nil || one[0] != 'x' {
		t.Fatalf("Go netpoll failed after native FD handling: %q, %v", one, err)
	}
}

func assertNativeTestFDContent(t *testing.T, fd int, want string) {
	t.Helper()
	buffer := make([]byte, len(want))
	read, err := unix.Read(fd, buffer)
	if err != nil || read != len(buffer) || string(buffer) != want {
		t.Fatalf("inherited FD %d = %q after %d bytes, %v; want %q", fd, buffer, read, err, want)
	}
}

func validateNativeTargetExtraFileCount(count int) error {
	if count < 0 || count > maxNativeTargetExtraFiles {
		return errors.New("native target supports at most one inherited file")
	}
	return nil
}

// The helper's FDs 3 and 4 carry the request and status pipes. os/exec places
// the only optional target file at FD 5. A zero-file launch must leave FD 5
// alone: the Go runtime can allocate its epoll descriptor there during init.
func remapNativeTargetExtraFiles(count int) error {
	if err := validateNativeTargetExtraFileCount(count); err != nil {
		return err
	}
	if count == 0 {
		return nil
	}
	if _, err := unix.FcntlInt(5, unix.F_GETFD, 0); err != nil {
		return fmt.Errorf("native helper missing inherited target fd 5: %w", err)
	}
	if err := unix.Dup3(5, 3, 0); err != nil {
		return fmt.Errorf("native helper target fd 3: %w", err)
	}
	if err := unix.Close(5); err != nil {
		return fmt.Errorf("close native helper inherited target fd 5: %w", err)
	}
	return nil
}

type nativeExecRequest struct {
	Path      string           `json:"path"`
	Args      []string         `json:"args"`
	Env       []string         `json:"env"`
	Identity  WorkloadIdentity `json:"identity"`
	ParentPID int              `json:"parent_pid"`
	// A nil count is an invalid protocol request, including for zero files.
	ExtraFileCount *int `json:"extra_file_count"`
}

func init() {
	if len(os.Args) == 2 && os.Args[1] == workloadHelperArgument {
		runNativeWorkloadHelper()
	}
}

// The helper is part of the same binary. It is the only root userspace code
// launched into a role cgroup; it must drop all privilege before execing the
// artifact. Its status FD closes on successful exec and reports pre-exec errors.
func runNativeWorkloadHelper() {
	// prctl, credential changes, and exec must affect the same Linux task.
	// A Go scheduler migration here would silently undo the security boundary.
	runtime.LockOSThread()
	status := os.NewFile(4, "native-exec-status")
	fail := func(err error) {
		if status != nil {
			_, _ = io.WriteString(status, err.Error())
		}
		os.Exit(113)
	}
	requestFile := os.NewFile(3, "native-exec-request")
	if requestFile == nil || status == nil {
		fail(errors.New("native helper missing protocol files"))
	}
	data, err := io.ReadAll(io.LimitReader(requestFile, 128<<10+1))
	if err != nil || len(data) > 128<<10 {
		fail(errors.New("native helper request invalid"))
	}
	_ = requestFile.Close()
	var request nativeExecRequest
	if err := json.Unmarshal(data, &request); err != nil || !validNativeExecRequest(request) {
		fail(errors.New("native helper request malformed"))
	}
	// Move the status FD above target ExtraFiles before installing target FD 3.
	statusFD, err := unix.FcntlInt(status.Fd(), unix.F_DUPFD_CLOEXEC, 10)
	if err != nil {
		fail(fmt.Errorf("native helper status fd: %w", err))
	}
	_ = status.Close()
	status = os.NewFile(uintptr(statusFD), "native-exec-status")
	if err := remapNativeTargetExtraFiles(*request.ExtraFileCount); err != nil {
		fail(err)
	}
	if err := dropNativePrivileges(request.Identity, request.ParentPID); err != nil {
		fail(err)
	}
	if err := syscall.Exec(request.Path, request.Args, request.Env); err != nil {
		fail(fmt.Errorf("exec native workload: %w", err))
	}
}

func validNativeExecRequest(request nativeExecRequest) bool {
	return request.Path != "" && len(request.Args) != 0 && request.ParentPID >= 2 &&
		request.Identity.UID != 0 && request.Identity.GID != 0 && request.ExtraFileCount != nil &&
		validateNativeTargetExtraFileCount(*request.ExtraFileCount) == nil
}

func validateNativeTargetExtraFileCount(count int) error {
	if count < 0 || count > maxNativeTargetExtraFiles {
		return errors.New("native target supports at most one inherited file")
	}
	return nil
}

func remapNativeTargetExtraFiles(count int) error {
	if err := validateNativeTargetExtraFileCount(count); err != nil {
		return err
	}
	if count == 0 {
		return nil
	}
	if _, err := unix.FcntlInt(5, unix.F_GETFD, 0); err != nil {
		return fmt.Errorf("native helper missing inherited target fd 5: %w", err)
	}
	if err := unix.Dup3(5, 3, 0); err != nil {
		return fmt.Errorf("native helper target fd 3: %w", err)
	}
	if err := unix.Close(5); err != nil {
		return fmt.Errorf("close native helper inherited target fd 5: %w", err)
	}
	return nil
}

func dropNativePrivileges(identity WorkloadIdentity, parentPID int) error {
	if os.Geteuid() != 0 || identity.UID == 0 || identity.GID == 0 {
		return errors.New("native helper requires root and nonzero workload identity")
	}
	// The helper inherits the protected supervisor's scheduling attributes.
	// Reset them while root before the irreversible UID and capability drop.
	if err := unix.Setpriority(unix.PRIO_PROCESS, 0, 0); err != nil {
		return fmt.Errorf("reset native workload nice: %w", err)
	}
	if err := resetNativeWorkloadOOMScore("/proc/self/oom_score_adj"); err != nil {
		return err
	}
	if err := setNativeIOPriority(0, nativeIOPriorityNeutral); err != nil {
		return fmt.Errorf("reset native workload I/O priority: %w", err)
	}
	if err := unix.Prctl(unix.PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0); err != nil {
		return fmt.Errorf("set native no_new_privs: %w", err)
	}
	if err := unix.Prctl(unix.PR_CAP_AMBIENT, unix.PR_CAP_AMBIENT_CLEAR_ALL, 0, 0, 0); err != nil {
		return fmt.Errorf("clear native ambient caps: %w", err)
	}
	data, err := os.ReadFile("/proc/sys/kernel/cap_last_cap")
	if err != nil {
		return fmt.Errorf("read native cap bound: %w", err)
	}
	last, err := strconv.Atoi(strings.TrimSpace(string(data)))
	if err != nil || last < 0 || last > 255 {
		return errors.New("invalid native cap bound")
	}
	for capability := range last + 1 {
		if err := unix.Prctl(unix.PR_CAPBSET_DROP, uintptr(capability), 0, 0, 0); err != nil {
			return fmt.Errorf("drop native bounding capability %d: %w", capability, err)
		}
	}
	var inherited [2]unix.CapUserData
	inheritedHeader := unix.CapUserHeader{Version: unix.LINUX_CAPABILITY_VERSION_3}
	if err := unix.Capget(&inheritedHeader, &inherited[0]); err != nil {
		return fmt.Errorf("inspect native inheritable capabilities: %w", err)
	}
	for index := range inherited {
		inherited[index].Inheritable = 0
	}
	if err := unix.Capset(&inheritedHeader, &inherited[0]); err != nil {
		return fmt.Errorf("clear native inheritable capabilities: %w", err)
	}
	if err := unix.Setgroups(nil); err != nil {
		return fmt.Errorf("clear native supplementary groups: %w", err)
	}
	if err := unix.Setresgid(int(identity.GID), int(identity.GID), int(identity.GID)); err != nil {
		return fmt.Errorf("drop native group: %w", err)
	}
	if err := unix.Setresuid(int(identity.UID), int(identity.UID), int(identity.UID)); err != nil {
		return fmt.Errorf("drop native user: %w", err)
	}
	// Credential transitions clear Pdeathsig. Rearm it and check for a parent
	// death between clone3 and this point before allowing target exec.
	if err := unix.Prctl(unix.PR_SET_PDEATHSIG, uintptr(syscall.SIGKILL), 0, 0, 0); err != nil {
		return fmt.Errorf("rearm native parent death: %w", err)
	}
	if os.Getppid() != parentPID {
		return errors.New("native supervisor died before workload exec")
	}
	var caps [2]unix.CapUserData
	header := unix.CapUserHeader{Version: unix.LINUX_CAPABILITY_VERSION_3}
	if err := unix.Capget(&header, &caps[0]); err != nil {
		return fmt.Errorf("verify native capabilities: %w", err)
	}
	for _, capset := range caps {
		if capset.Effective != 0 || capset.Permitted != 0 || capset.Inheritable != 0 {
			return errors.New("native workload retained capabilities")
		}
	}
	return nil
}

func resetNativeWorkloadOOMScore(path string) error {
	oomScore, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("read native workload OOM score adjustment: %w", err)
	}
	currentOOM := strings.TrimSpace(string(oomScore))
	adjustment, err := strconv.Atoi(currentOOM)
	if err != nil || adjustment < -1000 || adjustment > 1000 {
		return fmt.Errorf("invalid inherited native workload OOM score adjustment %q", currentOOM)
	}
	if adjustment >= 0 {
		return nil
	}
	if err := os.WriteFile(path, []byte("0"), 0); err != nil {
		return fmt.Errorf("reset native workload OOM score adjustment from %d: %w", adjustment, err)
	}
	oomScore, err = os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("verify native workload OOM score adjustment: %w", err)
	}
	if strings.TrimSpace(string(oomScore)) != "0" {
		return fmt.Errorf("native workload OOM score adjustment did not reset: %q", strings.TrimSpace(string(oomScore)))
	}
	return nil
}

func setNativeIOPriority(pid, priority int) error {
	_, _, errno := unix.Syscall(unix.SYS_IOPRIO_SET, 1, uintptr(pid), uintptr(priority))
	if errno != 0 {
		return errno
	}
	return nil
}

func readNativeIOPriority(pid int) (int, error) {
	value, _, errno := unix.Syscall(unix.SYS_IOPRIO_GET, 1, uintptr(pid), 0)
	if errno != 0 {
		return 0, errno
	}
	return int(value), nil
}

func assertNativeTestFDContent(t *testing.T, fd int, want string) {
	t.Helper()
	buffer := make([]byte, len(want))
	read, err := unix.Read(fd, buffer)
	if err != nil || read != len(buffer) || string(buffer) != want {
		t.Fatalf("inherited FD %d = %q after %d bytes, %v; want %q", fd, buffer, read, err, want)
	}
}

func TestNativeWorkloadHelperExecWithDeclaredExtraFiles(t *testing.T) {
	if os.Geteuid() != 0 {
		t.Skip("native helper root-to-tenant exec requires root")
	}
	parentOOM, err := os.ReadFile("/proc/self/oom_score_adj")
	if err != nil {
		t.Fatalf("read native helper parent OOM score adjustment: %v", err)
	}
	t.Logf("native helper parent OOM score adjustment=%q", strings.TrimSpace(string(parentOOM)))
	parentAdjustment, err := strconv.Atoi(strings.TrimSpace(string(parentOOM)))
	if err != nil || parentAdjustment < -1000 || parentAdjustment > 1000 {
		t.Fatalf("invalid native helper parent OOM score adjustment %q: %v", parentOOM, err)
	}
	expectedAdjustment := max(parentAdjustment, 0)
	if os.Getenv(nativeProtectedParentTestEnv) == "1" {
		priority, err := unix.Getpriority(unix.PRIO_PROCESS, 0)
		if err != nil || priority != 40 { // Linux returns 20-nice.
			t.Fatalf("protected parent raw priority = %d, %v; want 40 (nice -20)", priority, err)
		}
		if strings.TrimSpace(string(parentOOM)) != "-1000" {
			t.Fatalf("protected parent OOM score adjustment = %q, want -1000", parentOOM)
		}
		ioPriority, err := readNativeIOPriority(0)
		if err != nil || ioPriority != 2<<13 {
			t.Fatalf("protected parent I/O priority = %d, %v; want BestEffort/0", ioPriority, err)
		}
	}
	for _, count := range []int{0, 1} {
		t.Run(strconv.Itoa(count), func(t *testing.T) {
			requestRead, requestWrite, err := os.Pipe()
			if err != nil {
				t.Fatal(err)
			}
			defer requestRead.Close()
			defer requestWrite.Close()
			statusRead, statusWrite, err := os.Pipe()
			if err != nil {
				t.Fatal(err)
			}
			defer statusRead.Close()
			defer statusWrite.Close()
			request := nativeExecRequest{
				Path: "/proc/self/exe", Args: []string{"/proc/self/exe", "-test.run=^TestNativeHelperTenantTarget$"},
				Env: []string{
					nativeTenantTargetTestEnv + "=" + strconv.Itoa(count),
					nativeExpectedOOMTestEnv + "=" + strconv.Itoa(expectedAdjustment),
				},
				Identity: WorkloadIdentity{UID: 65534, GID: 65534}, ParentPID: os.Getpid(),
				ExtraFileCount: new(count),
			}
			wire, err := json.Marshal(request)
			if err != nil {
				t.Fatal(err)
			}
			if _, err := requestWrite.Write(wire); err != nil {
				t.Fatal(err)
			}
			if err := requestWrite.Close(); err != nil {
				t.Fatal(err)
			}
			ctx, cancel := context.WithTimeout(t.Context(), 10*time.Second)
			defer cancel()
			command := exec.CommandContext(ctx, "/proc/self/exe", workloadHelperArgument)
			command.Env = []string{}
			command.ExtraFiles = []*os.File{requestRead, statusWrite}
			if count == 1 {
				path := filepath.Join(t.TempDir(), "target-extra")
				if err := os.WriteFile(path, []byte("native-target-file"), 0o600); err != nil {
					t.Fatal(err)
				}
				file, err := os.Open(path)
				if err != nil {
					t.Fatal(err)
				}
				defer file.Close()
				command.ExtraFiles = append(command.ExtraFiles, file)
			}
			var output bytes.Buffer
			command.Stdout, command.Stderr = &output, &output
			if err := command.Start(); err != nil {
				t.Fatal(err)
			}
			if err := statusWrite.Close(); err != nil {
				t.Fatal(err)
			}
			if err := command.Wait(); err != nil {
				status, _ := io.ReadAll(statusRead)
				t.Fatalf("native helper count %d failed: %v; status: %s\n%s", count, err, status, output.String())
			}
			status, err := io.ReadAll(statusRead)
			if err != nil || len(status) != 0 {
				t.Fatalf("native helper count %d status %q, %v", count, status, err)
			}
		})
	}
}

func TestNativeHelperTenantTarget(t *testing.T) {
	wire, ok := os.LookupEnv(nativeTenantTargetTestEnv)
	if !ok {
		t.Skip("only the native helper execs this target")
	}
	count, err := strconv.Atoi(wire)
	if err != nil || count < 0 || count > 1 {
		t.Fatalf("invalid native helper target count %q", wire)
	}
	if os.Geteuid() != 65534 || os.Getegid() != 65534 {
		t.Fatalf("native target identity = %d:%d, want 65534:65534", os.Geteuid(), os.Getegid())
	}
	nice, err := unix.Getpriority(unix.PRIO_PROCESS, 0)
	// Linux's getpriority syscall returns 20-nice; x/sys exposes that raw value.
	if err != nil || nice != 20 {
		t.Fatalf("native target raw priority = %d, %v; want 20 (nice 0)", nice, err)
	}
	oom, err := os.ReadFile("/proc/self/oom_score_adj")
	adjustment, parseErr := strconv.Atoi(strings.TrimSpace(string(oom)))
	expected, expectedErr := strconv.Atoi(os.Getenv(nativeExpectedOOMTestEnv))
	if err != nil || parseErr != nil || expectedErr != nil || adjustment != expected {
		t.Fatalf("native target OOM score adjustment = %q, read error %v, parse error %v; want %d (parse error %v)", oom, err, parseErr, expected, expectedErr)
	}
	priority, err := readNativeIOPriority(0)
	if err != nil || priority != nativeIOPriorityNeutral {
		t.Fatalf("native target I/O priority = %d, %v; want BestEffort/4", priority, err)
	}
	if count == 1 {
		assertNativeTestFDContent(t, 3, "native-target-file")
	}
}

func verifyNativeExec(pid int, cgroupPath string, identity WorkloadIdentity) error {
	stat, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "stat"))
	if err != nil {
		return fmt.Errorf("native target exited before verification: %w", err)
	}
	if err := verifyNativeExecNice(stat); err != nil {
		return err
	}
	oomScore, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "oom_score_adj"))
	if err != nil {
		return fmt.Errorf("inspect native target OOM score adjustment: %w", err)
	}
	adjustment, err := strconv.Atoi(strings.TrimSpace(string(oomScore)))
	if err != nil || adjustment < 0 {
		return errors.New("native target retained protected supervisor OOM score adjustment")
	}
	ioPriority, err := readNativeIOPriority(pid)
	if err != nil {
		return fmt.Errorf("inspect native target I/O priority: %w", err)
	}
	if ioPriority != 0 && (ioPriority>>13 != 2 || ioPriority&((1<<13)-1) < 4) && ioPriority>>13 != 3 {
		return errors.New("native target retained protected supervisor I/O priority")
	}
	cmdline, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "cmdline"))
	if err != nil || len(cmdline) == 0 || bytes.Contains(cmdline, []byte(workloadHelperArgument)) {
		return errors.New("native helper did not exec the target")
	}
	if err := probeNativeTargetIdentity(pid, identity); err != nil {
		return err
	}
	contained, err := nativeCgroupContainsPID(cgroupPath, pid)
	if err != nil {
		return err
	}
	if !contained {
		return errors.New("native target escaped its role cgroup")
	}
	return nil
}

func verifyNativeExecNice(stat []byte) error {
	closing := bytes.LastIndexByte(stat, ')')
	if closing < 0 {
		return errors.New("native target has invalid process status")
	}
	fields := strings.Fields(string(stat[closing+1:]))
	if len(fields) <= 16 || fields[0] == "Z" || fields[0] == "X" || fields[0] == "x" {
		return errors.New("native target exited before verification")
	}
	// fields[0] is stat field 3 (state); fields[16] is field 19 (nice).
	// fields[17] is num_threads and cannot detect an inherited negative nice.
	nice, err := strconv.Atoi(fields[16])
	if err != nil || nice < 0 {
		return errors.New("native target retained protected supervisor nice")
	}
	return nil
}

type canceledCacheStore struct {
	ArtifactStore
	started  chan string
	canceled chan string
}

func (s canceledCacheStore) GetInfo(ctx context.Context, name string, _ ...jetstream.GetObjectInfoOpt) (*jetstream.ObjectInfo, error) {
	s.started <- name
	<-ctx.Done()
	s.canceled <- name
	return nil, ctx.Err()
}

func (c *Controller) readArtifactChunk(ctx context.Context, digest string, offset int64, length int) ([]byte, int64, error) {
	return c.readCachedArtifact(ctx, &c.workloadCache, maxArtifactBytes, digest, offset, length)
}

func (c *Controller) readCachedArtifact(ctx context.Context, cache *artifactCache, maxBytes int64, digest string, offset int64, length int) ([]byte, int64, error) {
	if err := ctx.Err(); err != nil {
		return nil, 0, err
	}
	c.cacheMu.Lock()
	defer c.cacheMu.Unlock()
	if c.cacheClosed {
		return nil, 0, errors.New("artifact cache is closed")
	}
	if cache.digest != digest || cache.file == nil {
		if !cache.downloading && !time.Now().Before(cache.retryAfter) {
			cache.downloading = true
			go c.downloadArtifact(cache, maxBytes, digest)
		}
		return nil, 0, errArtifactPreparing
	}
	if offset < 0 || offset >= cache.size {
		return nil, 0, errors.New("artifact offset is outside object")
	}
	count := min(int64(length), cache.size-offset)
	data := make([]byte, count)
	if _, err := cache.file.ReadAt(data, offset); err != nil {
		return nil, 0, err
	}
	return data, cache.size, nil
}

func (c *Controller) downloadArtifact(cache *artifactCache, maxBytes int64, digest string) {
	ctx, cancel := context.WithTimeout(c.cacheContext, 2*time.Minute)
	defer cancel()
	var downloaded *os.File
	var size int64
	var fetchErr error
	defer func() {
		c.cacheMu.Lock()
		defer c.cacheMu.Unlock()
		cache.downloading = false
		if c.cacheClosed || fetchErr != nil {
			if downloaded != nil {
				_ = downloaded.Close()
			}
			if fetchErr != nil {
				cache.retryAfter = time.Now().Add(3 * time.Second)
			}
			return
		}
		if cache.file != nil {
			_ = cache.file.Close()
		}
		cache.file = downloaded
		cache.digest = digest
		cache.size = size
	}()
	info, err := c.artifacts.GetInfo(ctx, "sha256-"+digest)
	if err != nil {
		fetchErr = err
		return
	}
	if info == nil || info.Deleted || info.Opts != nil && info.Opts.Link != nil || info.Size == 0 || info.Size > uint64(maxBytes) {
		fetchErr = errors.New("artifact metadata is invalid")
		return
	}
	js, err := jetstream.New(c.conn)
	if err != nil {
		fetchErr = err
		return
	}
	file, err := os.CreateTemp("", "ts-host-artifact-*")
	if err != nil {
		fetchErr = err
		return
	}
	_ = os.Remove(file.Name())
	downloaded = file
	if err := artifact.ReadVerified(ctx, js, c.artifacts, info.Bucket, "sha256-"+digest,
		digest, int64(info.Size), maxBytes, file); err != nil {
		fetchErr = err
		return
	}
	if err := file.Sync(); err != nil {
		fetchErr = err
		return
	}
	size = int64(info.Size)
}

func (c *Controller) closeCache() {
	c.cacheCancel()
	c.cacheMu.Lock()
	defer c.cacheMu.Unlock()
	c.cacheClosed = true
	for _, cache := range []*artifactCache{&c.workloadCache, &c.netbirdCache} {
		if cache.file != nil {
			_ = cache.file.Close()
			cache.file = nil
		}
	}
}

