func TestNetBirdArtifactSpoolRejectsOversizeMetadata(t *testing.T) {
	c, conn, store, _, _ := testController(t)
	defer c.closeCache()
	body := []byte("oversize metadata fixture")
	hash := sha256.Sum256(body)
	digest := hex.EncodeToString(hash[:])
	info, err := store.PutBytes(t.Context(), "sha256-"+digest, body)
	if err != nil {
		t.Fatal(err)
	}
	info.Size = client.MaxBinaryBytes + 1
	wire, err := json.Marshal(info)
	if err != nil {
		t.Fatal(err)
	}
	legacy, err := conn.JetStream()
	if err != nil {
		t.Fatal(err)
	}
	if _, err := legacy.Publish("$O."+info.Bucket+".M."+base64.URLEncoding.EncodeToString([]byte(info.Name)), wire); err != nil {
		t.Fatal(err)
	}
	var chunkReads atomic.Int64
	if _, err := conn.Subscribe("$JS.API.>", func(msg *nats.Msg) {
		var request struct {
			Subject string `json:"next_by_subj"`
		}
		if json.Unmarshal(msg.Data, &request) == nil && request.Subject != "" {
			chunkReads.Add(1)
		}
	}); err != nil {
		t.Fatal(err)
	}
	c.downloadArtifact(&c.netbirdCache, client.MaxBinaryBytes, digest)
	if c.netbirdCache.file != nil || c.netbirdCache.digest != "" || !time.Now().Before(c.netbirdCache.retryAfter) {
		t.Fatal("oversize NetBird object populated its bounded spool")
	}
	if err := conn.Flush(); err != nil {
		t.Fatal(err)
	}
	finished := make(chan struct{})
	if err := conn.Barrier(func() { close(finished) }); err != nil {
		t.Fatal(err)
	}
	select {
	case <-finished:
	case <-t.Context().Done():
		t.Fatal(t.Context().Err())
	}
	if chunkReads.Load() != 0 {
		t.Fatal("oversize NetBird metadata was allowed to fetch artifact chunks")
	}
}

func (m *memoryMutations) ReadHostMutation(_ context.Context, kind authority.HostMutationKind, subject string) (authority.LogEntry, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	entry, ok := m.entries[m.key(kind, subject)]
	if !ok {
		return authority.LogEntry{}, authority.ErrNotFound
	}
	return entry, nil
}

func (m *memoryMutations) CommitHostMutation(ctx context.Context, epoch uint64, kind authority.HostMutationKind, subject, operation string, expected uint64, payload []byte) (uint64, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	key := m.key(kind, subject)
	if m.entries[key].Sequence != expected {
		return 0, authority.ErrConflict
	}
	record, err := json.Marshal(struct {
		Version     int                        `json:"version"`
		Kind        authority.HostMutationKind `json:"kind"`
		Scope       string                     `json:"scope"`
		SubjectKey  string                     `json:"subject_key"`
		OperationID string                     `json:"operation_id"`
		Epoch       uint64                     `json:"epoch"`
		Payload     []byte                     `json:"payload"`
	}{1, kind, "gru", subject, operation, epoch, payload})
	if err != nil {
		return 0, err
	}
	ack, err := m.js.Publish(ctx, "ts.control.gru.host."+string(kind)+"."+subject, record)
	if err != nil {
		return 0, err
	}
	m.sequence = ack.Sequence
	m.entries[key] = authority.LogEntry{Kind: kind, SubjectKey: subject, OperationID: operation, Epoch: epoch, Sequence: m.sequence, Payload: append([]byte(nil), payload...)}
	return m.sequence, nil
}

